import Complex64Array = require( '@stdlib/array/complex64' );
import Complex64 = require( '@stdlib/complex/float32/ctor' );
import cgerc = require( './index' );


// TESTS //

// The function returns a Complex64Array...
{
	const x = new Complex64Array( 10 );
	const y = new Complex64Array( 10 );
	const A = new Complex64Array( 20 );
	const alpha = new Complex64( 0.5, 0.5 );

	cgerc( 'row-major', 10, 10, alpha, x, 1, y, 1, A, 10 ); // $ExpectType Complex64Array
}

// The compiler throws an error if the function is provided a first argument which is not a string...
{
	const x = new Complex64Array( 10 );
	const y = new Complex64Array( 10 );
	const A = new Complex64Array( 20 );
	const alpha = new Complex64( 0.5, 0.5 );

	cgerc( 10, 10, 10, alpha, x, 1, y, 1, A, 10 ); // $ExpectError
	cgerc( true, 10, 10, alpha, x, 1, y, 1, A, 10 ); // $ExpectError
	cgerc( false, 10, 10, alpha, x, 1, y, 1, A, 10 ); // $ExpectError
	cgerc( null, 10, 10, alpha, x, 1, y, 1, A, 10 ); // $ExpectError
	cgerc( undefined, 10, 10, alpha, x, 1, y, 1, A, 10 ); // $ExpectError
	cgerc( [], 10, 10, alpha, x, 1, y, 1, A, 10 ); // $ExpectError
	cgerc( {}, 10, 10, alpha, x, 1, y, 1, A, 10 ); // $ExpectError
	cgerc( ( x: number ): number => x, 10, 10, alpha, x, 1, y, 1, A, 10 ); // $ExpectError
}

