// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Complex64Array( 10 );
	const y = new Complex64Array( 10 );
	const A = new Complex64Array( 20 );
	const alpha = new Complex64( 0.5, 0.5 );

	cgerc(); // $ExpectError
	cgerc( 'row-major' ); // $ExpectError
	cgerc( 'row-major', 10 ); // $ExpectError
	cgerc( 'row-major', 10, 10 ); // $ExpectError
	cgerc( 'row-major', 10, 10, alpha ); // $ExpectError
	cgerc( 'row-major', 10, 10, alpha, x ); // $ExpectError
	cgerc( 'row-major', 10, 10, alpha, x, 1 ); // $ExpectError
	cgerc( 'row-major', 10, 10, alpha, x, 1, y ); // $ExpectError
	cgerc( 'row-major', 10, 10, alpha, x, 1, y, 1 ); // $ExpectError
	cgerc( 'row-major', 10, 10, alpha, x, 1, y, 1, A ); // $ExpectError
	cgerc( 'row-major', 10, 10, alpha, x, 1, y, 1, A, 10, 10 ); // $ExpectError
}

